=== FILE: apb_gpio.v ===
// apb_gpio: APB4 general-purpose I/O block with edge and level interrupts.
// Implements interface_spec.md (eval case rtl/apb-gpio) following
// microarchitecture.md: zero wait states, no bus state machine, every
// register 32 bits wide and masked to the existing pins by PINS.
module apb_gpio #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output wire [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

    // Register indices, paddr[5:2].
    localparam [3:0] IDX_DATA_OUT    = 4'd0;
    localparam [3:0] IDX_DIR         = 4'd1;
    localparam [3:0] IDX_DATA_IN     = 4'd2;
    localparam [3:0] IDX_INTR_RISE   = 4'd3;
    localparam [3:0] IDX_INTR_FALL   = 4'd4;
    localparam [3:0] IDX_INTR_HIGH   = 4'd5;
    localparam [3:0] IDX_INTR_LOW    = 4'd6;
    localparam [3:0] IDX_INTR_ENABLE = 4'd7;
    localparam [3:0] IDX_INTR_STATUS = 4'd8;

    // Bits 0 to N-1 set: the pins that exist.
    localparam [31:0] PINS = 32'hFFFF_FFFF >> (32 - N);

    // ------------------------------------------------------------------
    // APB decode (microarchitecture section 1)
    // ------------------------------------------------------------------
    wire       access     = psel & penable;
    wire [3:0] reg_idx    = paddr[5:2];
    wire       upper_zero = (paddr[ADDR_WIDTH-1:6] == {(ADDR_WIDTH-6){1'b0}});
    wire       mapped     = (paddr[1:0] == 2'b00) & upper_zero &
                            (reg_idx <= IDX_INTR_STATUS);
    wire       wr_en      = access & pwrite & mapped;
    wire       rd_en      = access & ~pwrite & mapped;

    // Byte strobes expanded to bits, limited to existing pins.
    wire [31:0] byte_mask = {{8{pstrb[3]}}, {8{pstrb[2]}},
                             {8{pstrb[1]}}, {8{pstrb[0]}}};
    wire [31:0] wmask     = byte_mask & PINS;
    wire [31:0] wbits     = pwdata & wmask;

    wire we_data_out    = wr_en & (reg_idx == IDX_DATA_OUT);
    wire we_dir         = wr_en & (reg_idx == IDX_DIR);
    wire we_rise_en     = wr_en & (reg_idx == IDX_INTR_RISE);
    wire we_fall_en     = wr_en & (reg_idx == IDX_INTR_FALL);
    wire we_high_en     = wr_en & (reg_idx == IDX_INTR_HIGH);
    wire we_low_en      = wr_en & (reg_idx == IDX_INTR_LOW);
    wire we_intr_en     = wr_en & (reg_idx == IDX_INTR_ENABLE);
    wire we_status      = wr_en & (reg_idx == IDX_INTR_STATUS);

    // ------------------------------------------------------------------
    // Registers (microarchitecture section 2)
    // ------------------------------------------------------------------
    reg [31:0] data_out_q;
    reg [31:0] dir_q;
    reg [31:0] rise_en_q;
    reg [31:0] fall_en_q;
    reg [31:0] high_en_q;
    reg [31:0] low_en_q;
    reg [31:0] intr_en_q;
    reg [31:0] status_q;
    reg [31:0] in_q;
    reg [31:0] in_prev_q;

    // gpio_in widened to 32 bits, zeros above N.
    wire [31:0] gpio_in_w;
    genvar gi;
    generate
        for (gi = 0; gi < 32; gi = gi + 1) begin : g_in
            if (gi < N) begin : g_pin
                assign gpio_in_w[gi] = gpio_in[gi];
            end else begin : g_none
                assign gpio_in_w[gi] = 1'b0;
            end
        end
    endgenerate

    // ------------------------------------------------------------------
    // Detection and status (microarchitecture section 3)
    // ------------------------------------------------------------------
    wire [31:0] rise_ev  = in_q & ~in_prev_q;
    wire [31:0] fall_ev  = ~in_q & in_prev_q;
    wire [31:0] detected = ((rise_ev & rise_en_q) | (fall_ev & fall_en_q) |
                            (in_q & high_en_q) | (~in_q & low_en_q)) & PINS;
    wire [31:0] clr      = we_status ? wbits : 32'd0;
    wire [31:0] status_d = (status_q & ~clr) | detected;

    always @(posedge pclk) begin
        if (!presetn) begin
            data_out_q <= 32'd0;
            dir_q      <= 32'd0;
            rise_en_q  <= 32'd0;
            fall_en_q  <= 32'd0;
            high_en_q  <= 32'd0;
            low_en_q   <= 32'd0;
            intr_en_q  <= 32'd0;
            status_q   <= 32'd0;
            in_q       <= 32'd0;
            in_prev_q  <= 32'd0;
        end else begin
            if (we_data_out) data_out_q <= (data_out_q & ~wmask) | wbits;
            if (we_dir)      dir_q      <= (dir_q      & ~wmask) | wbits;
            if (we_rise_en)  rise_en_q  <= (rise_en_q  & ~wmask) | wbits;
            if (we_fall_en)  fall_en_q  <= (fall_en_q  & ~wmask) | wbits;
            if (we_high_en)  high_en_q  <= (high_en_q  & ~wmask) | wbits;
            if (we_low_en)   low_en_q   <= (low_en_q   & ~wmask) | wbits;
            if (we_intr_en)  intr_en_q  <= (intr_en_q  & ~wmask) | wbits;
            status_q  <= status_d;
            in_q      <= gpio_in_w;
            in_prev_q <= in_q;
        end
    end

    // ------------------------------------------------------------------
    // Read data and responses
    // ------------------------------------------------------------------
    reg [31:0] rdata_mux;
    always @(*) begin
        case (reg_idx)
            IDX_DATA_OUT:    rdata_mux = data_out_q;
            IDX_DIR:         rdata_mux = dir_q;
            IDX_DATA_IN:     rdata_mux = in_q;
            IDX_INTR_RISE:   rdata_mux = rise_en_q;
            IDX_INTR_FALL:   rdata_mux = fall_en_q;
            IDX_INTR_HIGH:   rdata_mux = high_en_q;
            IDX_INTR_LOW:    rdata_mux = low_en_q;
            IDX_INTR_ENABLE: rdata_mux = intr_en_q;
            IDX_INTR_STATUS: rdata_mux = status_q;
            default:         rdata_mux = 32'd0;
        endcase
    end

    assign prdata   = rd_en ? rdata_mux : 32'd0;
    assign pready   = 1'b1;
    assign pslverr  = access & (~mapped | (pwrite & (reg_idx == IDX_DATA_IN)));
    assign gpio_out = data_out_q[N-1:0];
    assign gpio_oe  = dir_q[N-1:0];
    assign irq      = |(status_q & intr_en_q);

`ifdef FORMAL
    // Design-intent properties. No proof job is submitted with this task.
    reg f_past_valid;
    initial f_past_valid = 1'b0;

    always @(*) begin
        assert(pready == 1'b1);
        if (!access) begin
            assert(prdata == 32'd0);
            assert(pslverr == 1'b0);
        end
        if (access && !mapped) begin
            assert(prdata == 32'd0);
            assert(pslverr == 1'b1);
        end
    end

    always @(posedge pclk) begin
        f_past_valid <= 1'b1;
        if (f_past_valid && !$past(presetn)) begin
            assert(data_out_q == 32'd0);
            assert(dir_q == 32'd0);
            assert(intr_en_q == 32'd0);
            assert(status_q == 32'd0);
            assert(in_q == 32'd0);
            assert(in_prev_q == 32'd0);
        end
    end
`endif

endmodule
=== END FILE ===
