// apb_gpio_tb: directed self-checking testbench for apb_gpio.
// Runs the same suite on an N = 8 instance and an N = 32 instance.
// Inputs change 1 time unit after a falling edge or a rising edge;
// outputs are checked 1 time unit after the falling edge (before the
// completing rising edge) or 1 time unit after a rising edge.
module apb_gpio_tb;

    reg         pclk;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    reg  [31:0] gin;
    reg         which;          // 0: N = 8 instance, 1: N = 32 instance
    reg  [31:0] pm;             // pin mask of the instance under test

    reg  [31:0] shadow;
    reg  [31:0] st;
    reg  [31:0] pp;
    reg  [31:0] qq;
    reg  [31:0] hh;
    reg  [31:0] ll;
    integer     passed;
    integer     failed;
    integer     phase;
    reg  [8*64-1:0] nonce;

    wire        psel8     = psel & ~which;
    wire        penable8  = penable & ~which;
    wire        psel32    = psel & which;
    wire        penable32 = penable & which;

    wire [31:0] prdata8;
    wire [31:0] prdata32;
    wire        pready8;
    wire        pready32;
    wire        pslverr8;
    wire        pslverr32;
    wire [7:0]  gout8;
    wire [7:0]  goe8;
    wire [31:0] gout32;
    wire [31:0] goe32;
    wire        irq8;
    wire        irq32;

    apb_gpio #(.ADDR_WIDTH(8), .N(8)) dut8 (
        .pclk(pclk), .presetn(presetn), .paddr(paddr),
        .psel(psel8), .penable(penable8), .pwrite(pwrite),
        .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata8),
        .pready(pready8), .pslverr(pslverr8),
        .gpio_in(gin[7:0]), .gpio_out(gout8), .gpio_oe(goe8), .irq(irq8)
    );

    apb_gpio #(.ADDR_WIDTH(8), .N(32)) dut32 (
        .pclk(pclk), .presetn(presetn), .paddr(paddr),
        .psel(psel32), .penable(penable32), .pwrite(pwrite),
        .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata32),
        .pready(pready32), .pslverr(pslverr32),
        .gpio_in(gin), .gpio_out(gout32), .gpio_oe(goe32), .irq(irq32)
    );

    wire [31:0] prdata  = which ? prdata32  : prdata8;
    wire        pready  = which ? pready32  : pready8;
    wire        pslverr = which ? pslverr32 : pslverr8;
    wire [31:0] gout    = which ? gout32    : {24'd0, gout8};
    wire [31:0] goe     = which ? goe32     : {24'd0, goe8};
    wire        irq     = which ? irq32     : irq8;

    initial pclk = 1'b0;
    always #5 pclk = ~pclk;

    // ------------------------------------------------------------------
    // Checking helpers
    // ------------------------------------------------------------------
    task chk(input [31:0] got, input [31:0] exp, input integer tag);
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("phase %0d check %0d (N=%0d): got 0x%08h, expected 0x%08h",
                       phase, tag, (which ? 32 : 8), got, exp);
            end
        end
    endtask

    task chk_irq(input e);
        begin
            chk({31'd0, irq}, {31'd0, e}, 23);
        end
    endtask

    task chk_pins(input [31:0] e_out, input [31:0] e_oe, input e_irq);
        begin
            chk(gout, e_out, 20);
            chk(goe, e_oe, 21);
            chk({31'd0, irq}, {31'd0, e_irq}, 22);
        end
    endtask

    // Expected read/write register value after a strobed write.
    function [31:0] merge(input [31:0] old, input [31:0] d,
                          input [3:0] s, input [31:0] msk);
        reg [31:0] m;
        begin
            m = {{8{s[3]}}, {8{s[2]}}, {8{s[1]}}, {8{s[0]}}} & msk;
            merge = (old & ~m) | (d & m);
        end
    endfunction

    // ------------------------------------------------------------------
    // APB manager
    // ------------------------------------------------------------------
    task apb_xfer(input is_wr, input [7:0] a, input [31:0] d, input [3:0] s,
                  input [31:0] exp_rd, input exp_err,
                  input pin_en, input [31:0] pins);
        begin
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = is_wr;
            paddr   = a;
            pwdata  = d;
            pstrb   = s;
            if (pin_en) gin = pins;
            #1;
            chk({31'd0, pslverr}, 32'd0, 1);
            chk(prdata, 32'd0, 2);
            @(negedge pclk);
            penable = 1'b1;
            #1;
            chk({31'd0, pready}, 32'd1, 3);
            chk({31'd0, pslverr}, {31'd0, exp_err}, 4);
            if (!is_wr) chk(prdata, exp_rd, 5);
            @(posedge pclk);
            #1;
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            pstrb   = 4'h0;
        end
    endtask

    task apb_wr(input [7:0] a, input [31:0] d, input [3:0] s, input e);
        begin
            apb_xfer(1'b1, a, d, s, 32'd0, e, 1'b0, 32'd0);
        end
    endtask

    task apb_wr_p(input [7:0] a, input [31:0] d, input [3:0] s, input e,
                  input [31:0] pins);
        begin
            apb_xfer(1'b1, a, d, s, 32'd0, e, 1'b1, pins);
        end
    endtask

    task apb_rd(input [7:0] a, input [31:0] exp, input e);
        begin
            apb_xfer(1'b0, a, 32'd0, 4'h0, exp, e, 1'b0, 32'd0);
        end
    endtask

    task apb_rd_p(input [7:0] a, input [31:0] exp, input e, input [31:0] pins);
        begin
            apb_xfer(1'b0, a, 32'd0, 4'h0, exp, e, 1'b1, pins);
        end
    endtask

    task idle(input integer n);
        integer i;
        begin
            for (i = 0; i < n; i = i + 1) begin
                @(negedge pclk);
                #1;
                chk(prdata, 32'd0, 6);
                chk({31'd0, pslverr}, 32'd0, 7);
            end
        end
    endtask

    task set_pins(input [31:0] v);
        begin
            @(negedge pclk);
            gin = v;
        end
    endtask

    task do_reset;
        begin
            @(negedge pclk);
            presetn = 1'b0;
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = 8'h00;
            pwdata  = 32'd0;
            pstrb   = 4'h0;
            gin     = 32'd0;
            repeat (3) @(negedge pclk);
            chk_pins(32'd0, 32'd0, 1'b0);
            presetn = 1'b1;
        end
    endtask

    task chk_all_zero;
        begin
            apb_rd(8'h00, 32'd0, 1'b0);
            apb_rd(8'h04, 32'd0, 1'b0);
            apb_rd(8'h08, 32'd0, 1'b0);
            apb_rd(8'h0C, 32'd0, 1'b0);
            apb_rd(8'h10, 32'd0, 1'b0);
            apb_rd(8'h14, 32'd0, 1'b0);
            apb_rd(8'h18, 32'd0, 1'b0);
            apb_rd(8'h1C, 32'd0, 1'b0);
            apb_rd(8'h20, 32'd0, 1'b0);
            chk_pins(32'd0, 32'd0, 1'b0);
        end
    endtask

    task rw_step(input [7:0] a, input [31:0] d, input [3:0] s);
        begin
            apb_wr(a, d, s, 1'b0);
            shadow = merge(shadow, d, s, pm);
            apb_rd(a, shadow, 1'b0);
            if (a == 8'h00) chk(gout, shadow, 24);
            if (a == 8'h04) chk(goe, shadow, 25);
        end
    endtask

    task rw_test(input [7:0] a);
        begin
            shadow = 32'd0;
            rw_step(a, 32'hFFFF_FFFF, 4'hF);
            rw_step(a, 32'h0000_0000, 4'h5);
            rw_step(a, 32'hA5C3_5A3C, 4'h2);
            rw_step(a, 32'h1234_5678, 4'h8);
            rw_step(a, 32'hDEAD_BEEF, 4'h0);
            rw_step(a, 32'h0000_00C3, 4'h1);
            rw_step(a, 32'h6996_0F0F, 4'hE);
            rw_step(a, 32'h0000_0000, 4'hF);
        end
    endtask

    // ------------------------------------------------------------------
    // The suite, run once per instance
    // ------------------------------------------------------------------
    task run_suite;
        begin
            pp = 32'h8000_0011 & pm;    // edge pins
            qq = 32'h0000_0008 & pm;    // second edge pin
            hh = 32'h0100_0006 & pm;    // high-level pins
            ll = 32'h0010_0020 & pm;    // low-level pins

            // 1. Reset values
            phase = 1;
            do_reset;
            chk_all_zero;

            // 2. Read/write registers: strobes, bits above N, pins
            phase = 2;
            rw_test(8'h00);
            rw_test(8'h04);
            rw_test(8'h0C);
            rw_test(8'h10);
            rw_test(8'h14);
            rw_test(8'h18);
            rw_test(8'h1C);
            idle(2);
            apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
            apb_rd(8'h20, 32'd0, 1'b0);
            chk_pins(32'd0, 32'd0, 1'b0);

            // 3. DATA_IN: sampled input, read only
            phase = 3;
            apb_rd_p(8'h08, 32'h8000_00A5 & pm, 1'b0, 32'h8000_00A5);
            apb_rd(8'h08, 32'h8000_00A5 & pm, 1'b0);
            apb_wr(8'h08, 32'hFFFF_FFFF, 4'hF, 1'b1);
            apb_rd(8'h08, 32'h8000_00A5 & pm, 1'b0);
            apb_rd_p(8'h08, 32'h7FFF_FF5A & pm, 1'b0, 32'h7FFF_FF5A);
            apb_rd(8'h00, 32'd0, 1'b0);
            chk_pins(32'd0, 32'd0, 1'b0);
            set_pins(32'd0);
            idle(2);
            apb_rd(8'h08, 32'd0, 1'b0);
            apb_rd(8'h20, 32'd0, 1'b0);

            // 4. PSLVERR policy and unmapped addresses
            phase = 4;
            apb_wr(8'h00, 32'h3C3C_3C3C, 4'hF, 1'b0);
            apb_wr(8'h01, 32'hFFFF_FFFF, 4'hF, 1'b1);
            apb_wr(8'h02, 32'hFFFF_FFFF, 4'hF, 1'b1);
            apb_wr(8'h03, 32'hFFFF_FFFF, 4'hF, 1'b1);
            apb_wr(8'h24, 32'hFFFF_FFFF, 4'hF, 1'b1);
            apb_wr(8'h40, 32'hFFFF_FFFF, 4'hF, 1'b1);
            apb_wr(8'h44, 32'hFFFF_FFFF, 4'hF, 1'b1);
            apb_wr(8'h5C, 32'hFFFF_FFFF, 4'hF, 1'b1);
            apb_wr(8'h80, 32'hFFFF_FFFF, 4'hF, 1'b1);
            apb_wr(8'hFC, 32'hFFFF_FFFF, 4'hF, 1'b1);
            apb_wr(8'h3C, 32'hFFFF_FFFF, 4'hF, 1'b1);
            idle(1);
            apb_rd(8'h00, 32'h3C3C_3C3C & pm, 1'b0);
            apb_rd(8'h04, 32'd0, 1'b0);
            apb_rd(8'h1C, 32'd0, 1'b0);
            chk_pins(32'h3C3C_3C3C & pm, 32'd0, 1'b0);
            apb_rd(8'h01, 32'd0, 1'b1);
            apb_rd(8'h02, 32'd0, 1'b1);
            apb_rd(8'h24, 32'd0, 1'b1);
            apb_rd(8'h28, 32'd0, 1'b1);
            apb_rd(8'h3C, 32'd0, 1'b1);
            apb_rd(8'h40, 32'd0, 1'b1);
            apb_rd(8'h84, 32'd0, 1'b1);
            apb_rd(8'hFF, 32'd0, 1'b1);
            apb_wr(8'h00, 32'd0, 4'hF, 1'b0);
            chk_pins(32'd0, 32'd0, 1'b0);

            // 5. Rising edge: fires once, sticky, masked still sets status
            phase = 5;
            apb_wr(8'h0C, pp, 4'hF, 1'b0);
            set_pins(pp);
            apb_rd(8'h20, pp, 1'b0);
            chk_irq(1'b0);
            idle(3);
            apb_rd(8'h20, pp, 1'b0);
            apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
            apb_rd(8'h20, 32'd0, 1'b0);
            idle(2);
            apb_rd(8'h20, 32'd0, 1'b0);
            apb_wr(8'h0C, 32'd0, 4'hF, 1'b0);

            // 6. Falling edge
            phase = 6;
            apb_wr(8'h10, pp, 4'hF, 1'b0);
            set_pins(32'd0);
            apb_rd(8'h20, pp, 1'b0);
            apb_wr(8'h20, pp, 4'hF, 1'b0);
            apb_rd(8'h20, 32'd0, 1'b0);

            // 7. Both edges enabled
            phase = 7;
            apb_wr(8'h0C, pp, 4'hF, 1'b0);
            set_pins(pp);
            apb_rd(8'h20, pp, 1'b0);
            apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
            apb_rd(8'h20, 32'd0, 1'b0);
            set_pins(32'd0);
            apb_rd(8'h20, pp, 1'b0);
            apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
            apb_rd(8'h20, 32'd0, 1'b0);
            apb_wr(8'h10, 32'd0, 4'hF, 1'b0);

            // 8. One-cycle pulse, rising edge enabled
            phase = 8;
            set_pins(pp);
            set_pins(32'd0);
            apb_rd(8'h20, pp, 1'b0);
            apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
            apb_rd(8'h20, 32'd0, 1'b0);

            // 9. A detection beats a clear on the same edge
            phase = 9;
            apb_wr(8'h0C, pp | qq, 4'hF, 1'b0);
            set_pins(pp | qq);
            apb_rd(8'h20, pp | qq, 1'b0);
            set_pins(32'd0);
            idle(2);
            apb_rd(8'h20, pp | qq, 1'b0);
            apb_wr_p(8'h20, pp | qq, 4'hF, 1'b0, pp);
            apb_rd(8'h20, pp, 1'b0);
            apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
            apb_rd(8'h20, 32'd0, 1'b0);
            set_pins(32'd0);
            idle(2);
            apb_wr(8'h0C, 32'd0, 4'hF, 1'b0);

            // 10. High level: sets again after a clear while it holds
            phase = 10;
            apb_wr(8'h14, hh, 4'hF, 1'b0);
            set_pins(hh);
            apb_rd(8'h20, hh, 1'b0);
            apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
            apb_rd(8'h20, hh, 1'b0);
            set_pins(32'd0);
            idle(1);
            apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
            apb_rd(8'h20, 32'd0, 1'b0);
            apb_wr(8'h14, 32'd0, 4'hF, 1'b0);

            // 11. Low level
            phase = 11;
            apb_wr(8'h18, ll, 4'hF, 1'b0);
            apb_rd(8'h20, ll, 1'b0);
            apb_wr(8'h20, ll, 4'hF, 1'b0);
            apb_rd(8'h20, ll, 1'b0);
            set_pins(ll);
            idle(1);
            apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
            apb_rd(8'h20, 32'd0, 1'b0);
            apb_wr(8'h18, 32'd0, 4'hF, 1'b0);
            set_pins(32'd0);
            idle(2);

            // 12. Write-1-to-clear of some pending bits, with strobes
            phase = 12;
            apb_wr(8'h0C, 32'hFFFF_FFFF, 4'hF, 1'b0);
            set_pins(32'hFFFF_FFFF);
            apb_rd(8'h20, pm, 1'b0);
            apb_wr(8'h20, 32'h0000_0005, 4'hF, 1'b0);
            st = pm & ~32'h0000_0005;
            apb_rd(8'h20, st, 1'b0);
            apb_wr(8'h20, 32'hFFFF_FFFF, 4'h4, 1'b0);
            st = st & ~32'h00FF_0000;
            apb_rd(8'h20, st, 1'b0);
            apb_wr(8'h20, 32'h0000_0000, 4'hF, 1'b0);
            apb_rd(8'h20, st, 1'b0);
            apb_wr(8'h20, 32'h0000_00F0, 4'hE, 1'b0);
            apb_rd(8'h20, st, 1'b0);
            apb_wr(8'h21, 32'hFFFF_FFFF, 4'hF, 1'b1);
            apb_rd(8'h20, st, 1'b0);
            apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
            apb_rd(8'h20, 32'd0, 1'b0);
            apb_wr(8'h0C, 32'd0, 4'hF, 1'b0);
            set_pins(32'd0);
            idle(2);

            // 13. Interrupt mask
            phase = 13;
            apb_wr(8'h0C, pp, 4'hF, 1'b0);
            set_pins(pp);
            apb_rd(8'h20, pp, 1'b0);
            chk_irq(1'b0);
            apb_wr(8'h1C, qq, 4'hF, 1'b0);
            chk_irq(1'b0);
            apb_wr(8'h1C, 32'h0000_0001, 4'hF, 1'b0);
            chk_irq(1'b1);
            apb_wr(8'h20, 32'h0000_0001, 4'hF, 1'b0);
            chk_irq(1'b0);
            apb_rd(8'h20, pp & ~32'h0000_0001, 1'b0);
            apb_wr(8'h1C, 32'hFFFF_FFFF, 4'hF, 1'b0);
            chk_irq(1'b1);
            apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
            chk_irq(1'b0);
            apb_rd(8'h20, 32'd0, 1'b0);
            apb_wr(8'h1C, 32'd0, 4'hF, 1'b0);
            apb_wr(8'h0C, 32'd0, 4'hF, 1'b0);

            // 14. Reset again with state present
            phase = 14;
            apb_wr(8'h00, 32'h5A5A_5A5A, 4'hF, 1'b0);
            apb_wr(8'h04, 32'hA5A5_A5A5, 4'hF, 1'b0);
            apb_wr(8'h1C, 32'hFFFF_FFFF, 4'hF, 1'b0);
            apb_wr(8'h14, 32'hFFFF_FFFF, 4'hF, 1'b0);
            idle(2);
            chk_pins(32'h5A5A_5A5A & pm, 32'hA5A5_A5A5 & pm, 1'b1);
            do_reset;
            chk_all_zero;
        end
    endtask

    initial begin
        passed  = 0;
        failed  = 0;
        phase   = 0;
        nonce   = {(8*64){1'b0}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {(8*64){1'b0}};
        presetn = 1'b0;
        psel    = 1'b0;
        penable = 1'b0;
        pwrite  = 1'b0;
        paddr   = 8'h00;
        pwdata  = 32'd0;
        pstrb   = 4'h0;
        gin     = 32'd0;
        shadow  = 32'd0;
        st      = 32'd0;
        pp      = 32'd0;
        qq      = 32'd0;
        hh      = 32'd0;
        ll      = 32'd0;

        which = 1'b0;
        pm    = 32'h0000_00FF;
        run_suite;

        which = 1'b1;
        pm    = 32'hFFFF_FFFF;
        run_suite;

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
